const rec = $('Normalize Completion Report').item.json;
let mins;
try { mins = JSON.parse($json.output || $json.text || '{}'); } catch(e) { mins = {}; }
const minGrout = mins.min_grout_depth_ft ?? 20;
const minSepticSetback = mins.min_setback_septic_ft ?? 50;
const minPropertySetback = mins.min_setback_property_line_ft ?? 10;
const licenseExpired = new Date(rec.driller_license_expiry) < new Date();
const grout_ok = rec.grout_depth_ft >= minGrout;
const septic_ok = rec.setback_to_septic_ft >= minSepticSetback;
const property_ok = rec.setback_to_property_line_ft >= minPropertySetback;
const setbacks_met = grout_ok && septic_ok && property_ok;
const license_valid = !licenseExpired;
return { json: { ...rec, min_grout_depth_ft: minGrout, min_setback_septic_ft: minSepticSetback, min_setback_property_line_ft: minPropertySetback, license_valid, setbacks_met, grout_ok, septic_ok, property_ok } };

const rec = $('Check Grouting & Setback Compliance').item.json;
const reading = $json.measured_grout_depth_ft ?? rec.grout_depth_ft;
const tolerance = 1.0;
const cure_ok = (reading >= rec.min_grout_depth_ft - tolerance);
return { json: { ...rec, measured_grout_depth_ft: reading, cure_verified: cure_ok } };
